        newActiveRoute("C", pts(2100, 100, 1100, 100), T0);

        MutationResponse resp = transfer("tk-cycle", "req-" + rid("transfer"), List.of(
                item("A", 1, "C0_0", T0, "C1_0", T0),
                item("B", 1, "C1_0", T0, "C2_0", T0),
